-- Optional Oracle 11g+ fixture for compound trigger metadata.
-- Run common_core.sql first.

SET DEFINE OFF
SET SQLBLANKLINES ON
WHENEVER SQLERROR EXIT SQL.SQLCODE

BEGIN
  EXECUTE IMMEDIATE 'DROP TRIGGER OC_EMP_COMPOUND_AUD_TRG';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -4080 THEN RAISE; END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'DROP TABLE OC_11G_AUDIT_LOG CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/

CREATE TABLE OC_11G_AUDIT_LOG (
  AUDIT_ID NUMBER(10) NOT NULL,
  ACTION_NAME VARCHAR2(10) NOT NULL,
  EMPLOYEE_ID NUMBER(10),
  CREATED_AT DATE DEFAULT SYSDATE NOT NULL,
  CONSTRAINT OC_11G_AUDIT_LOG_PK PRIMARY KEY (AUDIT_ID)
);

CREATE OR REPLACE TRIGGER OC_EMP_COMPOUND_AUD_TRG
FOR INSERT OR UPDATE OR DELETE ON OC_EMPLOYEES
COMPOUND TRIGGER
  AFTER EACH ROW IS
    L_ACTION_NAME VARCHAR2(10);
    L_EMPLOYEE_ID NUMBER(10);
  BEGIN
    IF INSERTING THEN
      L_ACTION_NAME := 'INSERT';
      L_EMPLOYEE_ID := :NEW.EMPLOYEE_ID;
    ELSIF UPDATING THEN
      L_ACTION_NAME := 'UPDATE';
      L_EMPLOYEE_ID := :NEW.EMPLOYEE_ID;
    ELSE
      L_ACTION_NAME := 'DELETE';
      L_EMPLOYEE_ID := :OLD.EMPLOYEE_ID;
    END IF;

    INSERT INTO OC_11G_AUDIT_LOG (AUDIT_ID, ACTION_NAME, EMPLOYEE_ID)
    VALUES (OC_EMP_SEQ.NEXTVAL, L_ACTION_NAME, L_EMPLOYEE_ID);
  END AFTER EACH ROW;
END OC_EMP_COMPOUND_AUD_TRG;
/
SHOW ERRORS TRIGGER OC_EMP_COMPOUND_AUD_TRG

PROMPT Optional 11g compound trigger fixture loaded
